    'Publicar automáticamente tras cada cambio' => 'Publică automat după fiecare modificare',
    'SSH / rsync' => 'SSH / rsync',
    'Servidor' => 'Server',
    '10.147.17.20 o web.midominio.com' => '10.147.17.20 sau web.domeniultau.ro',
    'Carpeta remota' => 'Folder la distanță',
