    'No se puede crear {dest}' => 'Nu se poate crea {dest}',
    '{dest} no está vacía ni es de Universal Web: usa una carpeta exclusiva para esta web' => '{dest} nu este goală și nici nu aparține Universal Web: folosește un folder exclusiv pentru acest site',
